"""Build the local Python 3.12 beginner reference; examples are regression-tested."""
import json
from pathlib import Path
entries=[]
def add(category,name,kind,description,example,output,note=''):
    entries.append(dict(category=category,name=name,kind=kind,description=description,example=example,output=output,note=note))
M='Method';B='Built-in function';O='Operator'
add('str','text.lower()',M,'Make letters lowercase.','print("HELLO".lower())','hello')
add('str','text.upper()',M,'Make letters uppercase.','print("hello".upper())','HELLO')
add('str','text.title()',M,'Capitalize the start of words.','print("captain nova".title())','Captain Nova')
add('str','f"text {value}"','Syntax','Insert a value into text.','name = "Ari"\nprint(f"Hi, {name}!")','Hi, Ari!','The f prefix enables expressions in braces. A plain quoted string does not insert variables.')
add('str','text.strip()',M,'Trim whitespace at both ends.','print("  hello  ".strip())','hello')
add('str','text.split(separator)',M,'Split text into a list.','print("red,blue".split(","))',"['red', 'blue']")
add('str','text.replace(old, new)',M,'Replace matching text.','print("red balloon".replace("red", "blue"))','blue balloon')
add('str','separator.join(words)',M,'Join strings into one.','print("-".join(["sun", "moon"]))','sun-moon')
add('str','text.startswith(prefix)',M,'Check how text begins.','print("sunshine".startswith("sun"))','True')
add('str','text.find(part)',M,'Locate matching text.','print("balloon".find("loon"))','3','Returns the starting index, or -1 when not found. Indices begin at 0.')
add('int','number.bit_length()',M,'Count required binary digits.','number = 8\nprint(number.bit_length())','4')
add('int','number.bit_count()',M,'Count ones in binary.','number = 7\nprint(number.bit_count())','3')
add('int','abs(number)',B,'Find distance from zero.','print(abs(-7))','7')
add('int','str(number)',B,'Convert a number to text.','number = 7\nprint("Score: " + str(number))','Score: 7')
add('float','number.is_integer()',M,'Check for a whole value.','print((3.0).is_integer())','True')
add('float','number.as_integer_ratio()',M,'Express the exact stored ratio.','print((0.5).as_integer_ratio())','(1, 2)')
add('float','round(number, places)',B,'Round to decimal places.','print(round(3.14159, 2))','3.14','Floating-point values are approximate; some rounding results can be surprising.')
add('float','int(number)',B,'Convert by truncating toward zero.','print(int(-3.9))','-3')
add('list','items.append(value)',M,'Add one item at the end.','items = ["apple"]\nitems.append("pear")\nprint(items)',"['apple', 'pear']",'Changes the list in place and returns None. Print items to see the updated list.')
add('list','items.extend(values)',M,'Add several items.','items = [1]\nitems.extend([2, 3])\nprint(items)','[1, 2, 3]','Changes the list in place; returns None.')
add('list','items.insert(index, value)',M,'Insert at a chosen position.','items = ["a", "c"]\nitems.insert(1, "b")\nprint(items)',"['a', 'b', 'c']")
add('list','items.remove(value)',M,'Remove the first matching item.','items = [1, 2, 1]\nitems.remove(1)\nprint(items)','[2, 1]','Raises ValueError if the item is missing.')
add('list','items.pop()',M,'Remove and return the last item.','items = [1, 2, 3]\nprint(items.pop())\nprint(items)','3\n[1, 2]','Raises IndexError on an empty list. You can pass an index to pop a different position.')
add('list','items.sort()',M,'Sort the existing list.','items = [3, 1, 2]\nitems.sort()\nprint(items)','[1, 2, 3]','Changes the list in place; returns None. sorted(items) instead creates a new list.')
add('list','items.reverse()',M,'Reverse the existing list.','items = [1, 2, 3]\nitems.reverse()\nprint(items)','[3, 2, 1]')
add('list','len(items)',B,'Count the items.','print(len(["sun", "moon"]))','2')
add('dict','data.get(key, default)',M,'Read a key with a fallback.','data = {"color": "blue"}\nprint(data.get("size", "unknown"))','unknown')
add('dict','data.keys()',M,'View the keys.','data = {"color": "blue", "size": 2}\nprint(list(data.keys()))',"['color', 'size']")
add('dict','data.values()',M,'View the values.','data = {"color": "blue", "size": 2}\nprint(list(data.values()))',"['blue', 2]")
add('dict','data.items()',M,'View key/value pairs.','data = {"color": "blue"}\nfor key, value in data.items():\n    print(key, value)','color blue')
add('dict','data.update(values)',M,'Add or replace entries.','data = {"score": 1}\ndata.update({"score": 2})\nprint(data["score"])','2','Changes the dictionary in place; returns None.')
add('dict','data.pop(key)',M,'Remove and return a value.','data = {"score": 2}\nprint(data.pop("score"))\nprint(data)','2\n{}','A missing key raises KeyError unless you provide a fallback argument.')
add('dict','data.setdefault(key, default)',M,'Read or create an entry.','data = {}\nprint(data.setdefault("score", 0))\nprint(data)',"0\n{'score': 0}")
add('set','items.add(value)',M,'Add a unique item.','items = {1, 2}\nitems.add(2)\nitems.add(3)\nprint(sorted(items))','[1, 2, 3]','Sets have no guaranteed display order. sorted() makes these examples predictable.')
add('set','items.discard(value)',M,'Remove an item if present.','items = {1, 2}\nitems.discard(9)\nprint(sorted(items))','[1, 2]','Unlike remove(), discard() is safe when the item is missing.')
add('set','items.union(other)',M,'Combine unique items.','print(sorted({1, 2}.union({2, 3})))','[1, 2, 3]','Returns a new set; does not modify the original.')
add('set','items.intersection(other)',M,'Find shared items.','print(sorted({1, 2}.intersection({2, 3})))','[2]')
add('set','items.difference(other)',M,'Keep items absent from another set.','print(sorted({1, 2}.difference({2, 3})))','[1]')
add('set','len(items)',B,'Count unique items.','print(len({1, 1, 2}))','2')
add('tuple','items.count(value)',M,'Count matching values.','print((1, 2, 1).count(1))','2','Tuples cannot be changed in place.')
add('tuple','items.index(value)',M,'Find the first matching index.','print(("a", "b").index("b"))','1','Indices start at 0. A missing value raises ValueError.')
add('tuple','len(items)',B,'Count the tuple items.','print(len(("a", "b")))','2')
add('bool','not value',O,'Reverse a truth value.','print(not True)','False')
add('bool','left and right',O,'Require both truth values.','print(True and False)','False','With non-boolean operands, and returns an operand rather than converting it to bool.')
add('bool','left or right',O,'Accept either truth value.','print(True or False)','True','With non-boolean operands, or returns an operand rather than converting it to bool.')
add('bool','bool(value)',B,'Convert using truth testing.','print(bool([]))\nprint(bool([1]))','False\nTrue')
catalog={'categories':[{'id':key,'label':label} for key,label in [('all','All'),('str','String (str)'),('int','Integer (int)'),('float','Decimal (float)'),('list','List'),('dict','Dictionary'),('set','Set'),('tuple','Tuple'),('bool','Boolean')]],'entries':entries}
target=Path(__file__).resolve().parents[1]/'local/app/static/helper.json'
target.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Built {len(entries)} local reference entries.')
